p.me:
\frac00\text{ may hide a hole.}
\qquad
\frac{\text{nonzero}}0\text{ usually signals an asymptote.}

\begin{array}{c|c|c}
\textbf{degrees} \amp \textbf{example} \amp \textbf{behavior as }x\to\infty\\
\hline
\deg p<\deg q
\amp
\dfrac{x+1}{x^2+4}
\amp
0\\
\deg p=\deg q
\amp
\dfrac{3x^2-x+1}{x^2+4}
\amp
\dfrac{\text{leading coefficient of }p}{\text{leading coefficient of }q}=3\\
\deg p>\deg q
\amp
\dfrac{x^2+1}{x}
\amp
\text{does not approach a finite number}
\end{array}

